109	
110	export interface ConfigRoutesOptions {
111	    router: Router;
112	    appConfig: AppConfig;
113	    /** Optional absolute path to `config.json`. Defaults to the tool-root `config.json`. */
114	    configPath?: string;
115	    /** Optional `PollingManager`. When provided, PUT /api/config/polling restarts the loop. */
116	    pollingManager?: PollingManager;
117	    /** Optional `ErrorLogManager`. When provided, credential mutations are audit-logged. */
118	    errorLogManager?: ErrorLogManager;
119	}
120	
121	/**
122	 * Registers REST endpoints for managing application configuration in
123	 * `config.json`.
124	 *
125	 * **Credentials endpoints:**
126	 *
127	 * | Method | Path                              | Description               |
128	 * |--------|-----------------------------------|---------------------------|
129	 * | GET    | /api/config/credentials           | List credentials (masked) |
130	 * | PUT    | /api/config/credentials           | Add / update an entry     |
131	 * | DELETE | /api/config/credentials/:id       | Remove an entry           |
132	 *
133	 * `GET` returns a `GitCredentialEntry[]` array with tokens masked (`****` + last 4 chars).
134	 *
135	 * `PUT` request body: `{ id?: string, label: string, host: string, token: string }`.
136	 * When `id` is omitted, an ID is auto-generated from `label` as a kebab-case string
137	 * with a numeric suffix (-2, -3, …) appended on collision.
138	 * When `id` matches an existing entry, that entry is updated in-place (upsert).
139	 * Response: the updated `GitCredentialEntry[]` array with tokens masked.
140	 *
141	 * `DELETE` response: the remaining `GitCredentialEntry[]` array with tokens masked
142	 * (empty array `[]` when the last entry is removed). Returns 404 when the `id` is unknown.
143	 *
144	 * **Polling endpoints:**
145	 *
146	 * | Method | Path                    | Description                                          |
147	 * |--------|-------------------------|------------------------------------------------------|
148	 * | GET    | /api/config/polling     | Return current `gitPollingIntervalSeconds`           |
149	 * | PUT    | /api/config/polling     | Update the polling interval (min 10 s, max 86400 s)  |
150	 *
151	 * **Webserver URL endpoints:**
152	 *
153	 * | Method | Path                         | Description                              |
154	 * |--------|------------------------------|------------------------------------------|
155	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
156	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
157	 *
158	 * **Notes display endpoints:**
159	 *
160	 * | Method | Path                          | Description                                                                                                         |
161	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
162	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
163	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
164	 *
165	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
166	 * are persisted to `config.json` via `saveConfigField()`.
167	 *
168	 * **Security:** tokens are never returned in full — only the last 4 characters
169	 * are exposed. The `host` field is validated to reject `/`, `\`, null bytes,
170	 * and whitespace (see WP-004 / constraints.md § Hostname Format).
171	 *
172	 * @param options - Named-options bag.
173	 * @param options.router - Express-style router to register routes on.
174	 * @param options.appConfig - Live application config object (mutated in-place on PUT).
175	 * @param options.configPath - Optional absolute path to `config.json`. Defaults to the tool-root `config.json`.
176	 * @param options.pollingManager - Optional `PollingManager`; when provided, `PUT /api/config/polling` restarts the polling loop.
177	 * @param options.errorLogManager - Optional `ErrorLogManager`; when provided, credential mutations (create, update, delete) are audit-logged at `Severity: 'audit'`, `Source: 'credential-audit'`.
178	 */
179	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
180	    const { router, appConfig, configPath, pollingManager, errorLogManager } = options;
181	    // ------------------------------------------------------------------
182	    // GET /api/config/credentials — list all (tokens masked)
183	    // Returns GitCredentialEntry[] with tokens masked.
184	    // ------------------------------------------------------------------
185	    router.get('/api/config/credentials', (
186	        _req: IncomingMessage,
187	        res: ServerResponse,
188	        _params: Record<string, string>,
189	    ): void => {
190	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
191	    });
192	
193	    // ------------------------------------------------------------------
194	    // PUT /api/config/credentials — add or update a single entry
195	    //
196	    // Request body: { id?: string, label: string, host: string, token: string }
197	    //
198	    // - When `id` is omitted: auto-generates a kebab-case ID from `label`,
199	    //   appending a numeric suffix (-2, -3, …) if needed to avoid collisions.
200	    //   Always creates a new entry.
201	    // - When `id` is provided and matches an existing entry: upserts (replaces)
202	    //   the existing entry in-place.
203	    // - When `id` is provided and does NOT match any existing entry: creates a
204	    //   new entry with the given ID (after checking the ID is not already taken).
205	    //
206	    // Returns 400 when the resulting ID would collide with an existing entry
207	    // that is NOT the one being updated (duplicate-ID rejection).
208	    // ------------------------------------------------------------------
209	    router.put('/api/config/credentials', async (
210	        req: IncomingMessage,
211	        res: ServerResponse,
212	        _params: Record<string, string>,
213	    ): Promise<void> => {
214	        let body: unknown;
215	        try {
216	            body = await parseJsonBody(req);
217	        } catch (err) {
218	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
219	            return;
220	        }
221	
222	        if (!isPlainObject(body)) {
223	            sendError(res, 400, 'Request body must be a JSON object.');
224	            return;
225	        }
226	
227	        const { id, label, host, token } = body as {
228	            id?: unknown;
229	            label?: unknown;
230	            host?: unknown;
231	            token?: unknown;
232	        };
233	
234	        // Validate required string fields.
235	        if (typeof label !== 'string' || label.trim() === '') {
236	            sendError(res, 400, 'Missing or invalid field "label": must be a non-empty string.');
237	            return;
238	        }
239	        if (typeof host !== 'string' || host.trim() === '') {
240	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
241	            return;
242	        }
243	        // Reject host values containing path separators, null bytes, or whitespace —
244	        // a hostname should contain none of these characters.
245	        if (/[/\\\0\s]/.test(host)) {
246	            sendError(res, 400, 'Invalid field "host": must not contain /, \\, null bytes, or whitespace.');
247	            return;
248	        }
249	        if (typeof token !== 'string' || token.trim() === '') {
250	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
251	            return;
252	        }
253	
254	        // Validate optional `id` field when provided.
255	        if (id !== undefined && (typeof id !== 'string' || id.trim() === '')) {
256	            sendError(res, 400, 'Field "id", when provided, must be a non-empty string.');
257	            return;
258	        }
259	
260	        // Per-field length limits.
261	        if (typeof id === 'string' && id.trim().length > MAX_CREDENTIAL_ID_LENGTH) {
262	            sendError(res, 400, `"id" exceeds maximum length of ${MAX_CREDENTIAL_ID_LENGTH} characters.`);
263	            return;
264	        }
265	        if (label.trim().length > MAX_CREDENTIAL_LABEL_LENGTH) {
266	            sendError(res, 400, `"label" exceeds maximum length of ${MAX_CREDENTIAL_LABEL_LENGTH} characters.`);
267	            return;
268	        }
269	        if (host.trim().length > MAX_CREDENTIAL_HOST_LENGTH) {
270	            sendError(res, 400, `"host" exceeds maximum length of ${MAX_CREDENTIAL_HOST_LENGTH} characters.`);
271	            return;
272	        }
273	        if (token.trim().length > MAX_CREDENTIAL_TOKEN_LENGTH) {
274	            sendError(res, 400, `"token" exceeds maximum length of ${MAX_CREDENTIAL_TOKEN_LENGTH} characters.`);
275	            return;
276	        }
277	
278	        const cleanLabel = label.trim();
279	        const cleanHost = host.trim();
280	        const cleanToken = token.trim();
281	
282	        const existingCredentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
283	
284	        let savedEntry: GitCredentialEntry;
285	        let auditOperation: string;
286	
287	        if (id !== undefined) {
